  -- ---------------------------------------------------------------- 200 LEVEL
  ('ABE 201', 'Introduction to Agricultural and Bioresources Engineering', 'University of Nigeria, Nsukka', 'Faculty of Engineering', 'Agricultural and Bioresources Engineering', '200 Level', 'first', 1, 'The human need for food, fiber and timber and the role of engineering in their production, processing, storage/preservation and transportation. Concept of Agriculture as crops and livestock production and of Bioresources as including Aquaculture and Forestry, among others. Definition of Agricultural and Bioresources Engineering and its unique position in the engineering professions. The specialty areas of Agricultural and Bioresources Engineering; their general introduction.', '["The human need for food, fiber and timber and the role of engineering in their production, processing, storage/preservation and transportation", "Concept of Agriculture as crops and livestock production and of Bioresources as including Aquaculture and Forestry, among others", "Definition of Agricultural and Bioresources Engineering and its unique position in the engineering professions", "The specialty areas of Agricultural and Bioresources Engineering; their general introduction"]'::jsonb, 'Faculty of Engineering handbook'),
